using System;
using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

namespace SecureWsServer
{
    public class RateLimitEntry
    {
        public long[] Timestamps;
        public int Head;
        public int Count;
        public readonly object SyncRoot = new object();

        public RateLimitEntry(int windowSize)
        {
            Timestamps = new long[windowSize];
            Head = 0;
            Count = 0;
        }
    }

    public class WebSocketRateLimiter
    {
        private readonly ConcurrentDictionary<string, RateLimitEntry> _clients = new();
        private readonly int _maxRequests;
        private readonly long _windowTicks;
        private readonly ILogger _logger;

        public WebSocketRateLimiter(int maxRequests, TimeSpan window, ILogger logger)
        {
            _maxRequests = maxRequests;
            _windowTicks = window.Ticks;
            _logger = logger;
        }

        public bool IsAllowed(string clientId, long currentTick)
        {
            var entry = _clients.GetOrAdd(clientId, _ => new RateLimitEntry(_maxRequests));

            lock (entry.SyncRoot)
            {
                // Purge expired timestamps
                long cutoff = currentTick - _windowTicks;
                int purged = 0;
                while (entry.Count > 0)
                {
                    int oldest = (entry.Head - entry.Count + entry.Timestamps.Length) % entry.Timestamps.Length;
                    if (entry.Timestamps[oldest] < cutoff)
                    {
                        entry.Count--;
                        purged++;
                    }
                    else break;
                }

                if (entry.Count >= _maxRequests)
                {
                    _logger.LogWarning("Rate limit exceeded for client {ClientId}", clientId);
                    return false;
                }

                // Record this request
                entry.Timestamps[entry.Head] = currentTick;
                entry.Head = (entry.Head + 1) % entry.Timestamps.Length;
                entry.Count++;
                return true;
            }
        }
    }

    public class AuditLogger
    {
        private readonly ILogger _logger;

        public AuditLogger(ILogger logger)
        {
            _logger = logger;
        }

        public void LogMessage(string clientId, string action, bool allowed)
        {
            _logger.LogInformation(
                "[AUDIT] Client={ClientId} Action={Action} Allowed={Allowed} Time={Time}",
                clientId, action, allowed, DateTime.UtcNow);
        }
    }

    public class ConnectionTracker
    {
        private readonly ConcurrentDictionary<string, int> _connectionCounts = new();
        private readonly int _maxConnectionsPerClient;

        public ConnectionTracker(int maxConnections)
        {
            _maxConnectionsPerClient = maxConnections;
        }

        public string ResolveClientIdentity(HttpContext context)
        {
            // Use X-Forwarded-For if behind proxy, otherwise remote IP
            var forwarded = context.Request.Headers["X-Forwarded-For"].ToString();
            if (!string.IsNullOrEmpty(forwarded))
            {
                // Take the leftmost IP (original client)
                var clientIp = forwarded.Split(',')[0].Trim();
                return clientIp;
            }
            return context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        }

        public bool TryConnect(string clientId)
        {
            var count = _connectionCounts.AddOrUpdate(clientId, 1, (_, c) => c + 1);
            return count <= _maxConnectionsPerClient;
        }

        public void Disconnect(string clientId)
        {
            _connectionCounts.AddOrUpdate(clientId, 0, (_, c) => Math.Max(0, c - 1));
        }
    }

    public class WebSocketHandler
    {
        private readonly WebSocketRateLimiter _rateLimiter;
        private readonly AuditLogger _audit;
        private readonly ConnectionTracker _tracker;

        public WebSocketHandler(WebSocketRateLimiter rateLimiter, AuditLogger audit, ConnectionTracker tracker)
        {
            _rateLimiter = rateLimiter;
            _audit = audit;
            _tracker = tracker;
        }

        public async Task HandleConnection(HttpContext context)
        {
            if (!context.WebSockets.IsWebSocketRequest)
            {
                context.Response.StatusCode = 400;
                return;
            }

            string clientId = _tracker.ResolveClientIdentity(context);

            if (!_tracker.TryConnect(clientId))
            {
                _audit.LogMessage(clientId, "CONNECT", false);
                context.Response.StatusCode = 429;
                return;
            }

            using var ws = await context.WebSockets.AcceptWebSocketAsync();
            _audit.LogMessage(clientId, "CONNECT", true);

            try
            {
                await ProcessMessages(ws, clientId);
            }
            finally
            {
                _tracker.Disconnect(clientId);
                _audit.LogMessage(clientId, "DISCONNECT", true);
            }
        }

        private async Task ProcessMessages(WebSocket ws, string clientId)
        {
            var buffer = new byte[4096];

            while (ws.State == WebSocketState.Open)
            {
                var result = await ws.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);

                if (result.MessageType == WebSocketMessageType.Close)
                {
                    await ws.CloseAsync(WebSocketCloseStatus.NormalClosure, "Bye", CancellationToken.None);
                    break;
                }

                long now = DateTime.UtcNow.Ticks;
                bool allowed = _rateLimiter.IsAllowed(clientId, now);
                _audit.LogMessage(clientId, "MESSAGE", allowed);

                if (!allowed)
                {
                    var errorMsg = Encoding.UTF8.GetBytes("{\"error\":\"rate_limited\"}");
                    await ws.SendAsync(new ArraySegment<byte>(errorMsg), WebSocketMessageType.Text, true, CancellationToken.None);
                    continue;
                }

                // Echo back the message (simulating processing)
                var msg = Encoding.UTF8.GetString(buffer, 0, result.Count);
                var response = Encoding.UTF8.GetBytes($"{{\"echo\":\"{msg}\"}}");
                await ws.SendAsync(new ArraySegment<byte>(response), WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }
    }
}
